<?php require_once __DIR__.'/../../includes/bootstrap.php';require_role('Administrator','Event');$pageTitle='Event Management';$rows=db()->query('SELECT * FROM vw_calendar_events ORDER BY start_at DESC LIMIT 100')->fetchAll();require __DIR__.'/../../includes/header.php';?><div class="admin-shell"><aside class="sidebar"><?php require __DIR__.'/../sidebar.php';?></aside><section class="admin-content"><div class="admin-top"><div><div class="eyebrow">Operations</div><h1 class="admin-title">Event management</h1></div></div><div class="panel table-wrap"><table class="table"><thead><tr><th>Event</th><th>Category</th><th>Venue</th><th>Schedule</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $e):?><tr><td><b><?=e($e['title'])?></b></td><td><?=e($e['category_name']??'—')?></td><td><?=e($e['venue_names']??'—')?></td><td><?=date('d M Y H:i',strtotime($e['start_at']))?></td><td><?=e($e['status'])?></td></tr><?php endforeach;?></tbody></table></div></section></div><?php require __DIR__.'/../../includes/footer.php'; ?>
